INSERT INTO public.dataset_requests (created_by, title, description, category, data_type, status, samples_needed, samples_collected, reward_amount, currency, deadline, quality_criteria, requirements, featured, approval_status, admin_notes, approved_by, approved_at, funding_model, total_budget, paid_amount, payment_status, commission_percentage, image_url)
VALUES
('6f6548f1-8a49-48e1-8a05-fa61435b880c', 'Urban Pedestrian Scenarios for AV Safety', 'CityDrive Labs is preparing a safety benchmark for Level-4 autonomous shuttles and needs short video clips capturing pedestrians interacting with crosswalks, construction zones, and curbside drop-offs across multiple cities. Contributors should document both day and night conditions and annotate any unusual behaviors (e-scooters, jaywalking, mobility aids).', 'computer-vision', 'video', 'active', 2400, 410, 12.5, 'USD', '2024-10-20'::date, ARRAY['Minimum 1080p resolution', 'Include ambient audio from the street', 'Capture both peak and off-peak traffic'], ARRAY['Clips must be recorded in public streets with visible safety signage', 'Include timestamp overlay or metadata', 'No identifiable faces of minors'], true, 'approved', 'Reviewed safety compliance deck and anonymization approach.', '835f1b30-f7ac-4358-91ce-2fbe205cac7d', '2024-06-10T13:45:00Z'::timestamptz, 'per_contribution', 30000, 5125, 'partial', 12, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/urban-pedestrian-av.jpg'),
('835f1b30-f7ac-4358-91ce-2fbe205cac7d', 'Multilingual Airline Support Emails', 'SkyBridge Airways is training a generative assistant to triage flight disruption emails in English, Spanish, French, and German. They need real examples of customer emails paired with anonymized airline responses, covering delays, baggage, schedule changes, and loyalty inquiries.', 'natural-language', 'text', 'active', 5000, 1120, 1.25, 'EUR', '2024-09-30'::date, ARRAY['Each email thread must include at least one customer and one agent message', 'Personal data must be redacted using provided macros', 'Tag language and issue category in the metadata template'], ARRAY['Accepts .eml or .txt exports from ticketing tools', 'Must include original send timestamps', 'Max 500 words per ticket'], true, 'approved', 'GDPR compliance memo signed off by legal.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-06-18T09:30:00Z'::timestamptz, 'per_contribution', 6250, 2450, 'partial', 10, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/airline-support-emails.jpg'),
('efd35106-f890-46b8-aa61-6528460b115a', 'Pediatric Respiratory Auscultation Sounds', 'Children''s Health Research UK is collecting high-quality stethoscope recordings to improve early detection of pediatric asthma and bronchiolitis. Contributors will upload de-identified lung sound clips captured with electronic stethoscopes, accompanied by basic clinical context fields.', 'healthcare', 'audio', 'active', 800, 95, 18.0, 'GBP', '2024-11-05'::date, ARRAY['Use provided auscultation protocol (anterior/posterior, four points)', 'Noise floor below -50 dB', 'Clip length between 15-30 seconds'], ARRAY['Only contributors with pediatric care certification', 'Upload anonymized patient age range and symptoms', 'Include device make/model'], false, 'approved', 'IRB exemption verified; store in encrypted bucket.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-06-22T16:15:00Z'::timestamptz, 'per_contribution', 14400, 1710, 'partial', 15, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/pediatric-auscultation.jpg'),
('622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', 'Industrial Robot Downtime Logs', 'Rivet Automation is aggregating downtime events from robotic welding cells to refine predictive maintenance models. Each submission should include PLC logs, maintenance annotations, and sensor snapshots for the affected shift.', 'robotics', 'mixed', 'active', 180, 28, 0, 'USD', '2024-12-01'::date, ARRAY['Logs must cover at least 6 continuous hours', 'Include root-cause label agreed by maintenance lead', 'Provide synchronized sensor exports (vibration, temperature)'], ARRAY['Upload PLC logs in CSV or JSON', 'Attach photo of affected station when possible', 'Sign confidentiality agreement before first upload'], false, 'approved', 'Finance approved $25k flat contract; milestone invoicing.', '622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', '2024-07-01T11:20:00Z'::timestamptz, 'upfront', 25000, 10000, 'partial', 9, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/robot-downtime-logs.jpg'),
('6f6548f1-8a49-48e1-8a05-fa61435b880c', 'Rare Plant Leaf Imagery', 'The International Botanic Exchange is cataloging high-resolution photographs of rare and endangered plant species to aid conservation modeling. Contributors should capture top, underside, and macro views of leaves and provide GPS proximity metadata.', 'computer-vision', 'image', 'active', 3200, 620, 4.5, 'USD', '2024-11-12'::date, ARRAY['Minimum 24MP RAW or high-quality JPEG', 'Include color calibration card in first frame', 'Add botanical name using provided taxonomy list'], ARRAY['Must include GPS coordinates within 50m accuracy', 'Upload leaf macro detail (disease markers)', 'Follow local permitting requirements'], false, 'approved', 'Verified CITES compliance waiver.', '835f1b30-f7ac-4358-91ce-2fbe205cac7d', '2024-06-28T08:05:00Z'::timestamptz, 'per_contribution', 14400, 2790, 'partial', 11, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/rare-plant-leaves.jpg'),
('331a9e3e-2e75-4277-bc04-cd73840c8dff', 'Non-native English Accent Speech Corpus', 'LinguaNova AI is expanding its contact center speech recognizer with accents from Central and Eastern Europe, South Asia, and West Africa. Contributors record scripted and spontaneous speech following the provided prompt packs.', 'speech-audio', 'audio', 'active', 4200, 980, 3.8, 'USD', '2024-09-12'::date, ARRAY['16 kHz, 16-bit PCM WAV format', 'No more than 2% background noise', 'Include accent self-identification in metadata'], ARRAY['Contributors must complete pronunciation survey', 'Upload both scripted and improvised recordings', 'One speaker per submission'], true, 'approved', 'QA spot-checking first 50 hours for calibration.', '622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', '2024-06-30T10:50:00Z'::timestamptz, 'per_contribution', 15960, 3724, 'partial', 12, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/accent-speech.jpg'),
('efd35106-f890-46b8-aa61-6528460b115a', 'De-identified Hospital Admission Summaries', 'CareFlow Analytics is building a triage recommender and requires de-identified emergency department admission summaries with structured triage decisions. Data should span cardiac, trauma, respiratory, and gastrointestinal chief complaints.', 'healthcare', 'text', 'active', 1600, 210, 6.0, 'USD', '2024-08-28'::date, ARRAY['Narrative length between 120-250 words', 'Use provided SNOMED CT code mappings', 'Remove direct identifiers per HIPAA Safe Harbor'], ARRAY['Upload triage acuity and disposition fields', 'Include facility type (academic/community)', 'Ensure clinician role is documented'], false, 'approved', 'PHI scrubber spot checks completed.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-07-02T14:10:00Z'::timestamptz, 'per_contribution', 9600, 1260, 'partial', 10, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/hospital-admission-summaries.jpg'),
('835f1b30-f7ac-4358-91ce-2fbe205cac7d', 'Drone Wildlife Observation Videos', 'WildScan Initiative is curating annotated drone footage of large mammals in savanna ecosystems to improve detection models for anti-poaching patrols. Submissions should include bounding-box annotations for each herd member and environmental notes.', 'computer-vision', 'video', 'active', 950, 185, 20.0, 'USD', '2024-10-05'::date, ARRAY['4K or stabilized 2.7K footage', 'Manual annotations must match provided schema', 'Log weather and time of day in metadata'], ARRAY['Comply with local UAV regulations', 'Minimum 45 seconds per clip', 'Upload GPS flight path GPX file'], true, 'approved', 'Insurance certificate received and stored.', '622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', '2024-07-03T09:40:00Z'::timestamptz, 'per_contribution', 19000, 4625, 'partial', 13, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/drone-wildlife-videos.jpg'),
('622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', 'Smart Home Energy Usage Streams', 'Enerlytics GmbH is aggregating multi-sensor time series from smart homes (electricity, HVAC, solar generation) to train demand-response forecasts. Contributors provide daily CSV exports and configuration metadata.', 'other', 'mixed', 'active', 600, 142, 75.0, 'EUR', '2024-09-18'::date, ARRAY['Sampling interval <= 5 minutes', 'Include at least 30 consecutive days', 'Provide separate channels for generation vs. consumption'], ARRAY['Upload device manifest (make/model)', 'Include building occupancy metadata', 'Anonymize address to postal code only'], false, 'approved', 'VAT invoice template sent to finance.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-06-27T17:25:00Z'::timestamptz, 'upfront', 45000, 22500, 'partial', 8, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/smart-home-energy.jpg'),
('6f6548f1-8a49-48e1-8a05-fa61435b880c', 'Rural Road Sign Photographs', 'Atlas Navigation is filling blind spots in its map data by sourcing imagery of rural road signage (warning, regulatory, informational) across North America and Australia. Each submission should include front and angled views under varied lighting.', 'computer-vision', 'image', 'active', 5400, 1540, 2.8, 'USD', '2024-10-30'::date, ARRAY['Minimum 12MP resolution', 'Tag retroreflective damage if present', 'Capture GPS coordinates and compass heading'], ARRAY['Provide both day and dusk versions when possible', 'No vehicle dashboard reflections', 'Upload signage classification tag'], false, 'approved', 'Custom signage taxonomy synced to UI.', '835f1b30-f7ac-4358-91ce-2fbe205cac7d', '2024-07-04T12:35:00Z'::timestamptz, 'per_contribution', 15120, 4312, 'partial', 11, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/rural-road-signs.jpg'),
('331a9e3e-2e75-4277-bc04-cd73840c8dff', 'Devanagari Handwritten Characters', 'ScriptLearn Labs is preparing a handwriting recognition benchmark focused on Devanagari characters and ligatures. Contributors submit scanned worksheet pages following tracing guides for balanced character coverage.', 'natural-language', 'image', 'active', 2600, 520, 3.2, 'USD', '2024-09-22'::date, ARRAY['Scan at 600 DPI grayscale', 'Ensure even lighting and no motion blur', 'Include contributor ID code in footer'], ARRAY['One handwriting style per submission', 'Upload completed consent form', 'Provide native language background info'], false, 'approved', 'Curriculum team verified glyph checklist.', '622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', '2024-06-29T15:05:00Z'::timestamptz, 'per_contribution', 8320, 1664, 'partial', 10, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/devanagari-handwriting.jpg'),
('92854a9e-6f3c-4a02-8c83-0e799fd0f46a', 'Public Transit Crowd Audio Profiles', 'MetroSense is studying perceived crowding levels on rapid transit lines. Contributors capture ambient audio during peak and off-peak hours and label perceived comfort, line name, and rolling stock type.', 'speech-audio', 'audio', 'active', 1800, 360, 5.75, 'USD', '2024-08-31'::date, ARRAY['44.1 kHz stereo or binaural recording', 'Record at least 90 seconds continuously', 'Tag perceived crowd level on 1-5 scale'], ARRAY['Capture both station dwell and in-car segments', 'Note exact time and direction of travel', 'Avoid conversations that can identify individuals'], false, 'approved', 'Transit authority release filed (NYC + Berlin).', '835f1b30-f7ac-4358-91ce-2fbe205cac7d', '2024-07-01T18:00:00Z'::timestamptz, 'per_contribution', 10350, 2070, 'partial', 11, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/transit-crowd-audio.jpg'),
('622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', 'AR Indoor Navigation Point Clouds', 'Wayfind XR is enhancing its indoor positioning engine and needs RGB-D point clouds of large public buildings (airports, malls, hospitals). Contributors will capture scans using supported LiDAR devices and upload aligned floorplan references.', 'robotics', 'mixed', 'active', 320, 54, 260.0, 'USD', '2024-11-18'::date, ARRAY['Point cloud density >= 300k points per scan', 'Align scans to building coordinates', 'Provide obstacle annotations (kiosks, signage)'], ARRAY['Upload signed property access letter', 'Capture at least two floors per building', 'Include 360-degree panoramic stills'], true, 'approved', 'Enterprise SLA signed; project in premium tier.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-07-05T08:42:00Z'::timestamptz, 'upfront', 83200, 41600, 'partial', 9, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/indoor-nav-pointcloud.jpg'),
('92854a9e-6f3c-4a02-8c83-0e799fd0f46a', 'Sign Language Gesture Clips', 'SignSpeak Foundation is expanding its ASL-to-text translation dataset with new contributors across age groups. Upload 5-15 second RGB video clips for each targeted sign, following the provided framing and lighting guidelines.', 'computer-vision', 'video', 'active', 3600, 640, 7.0, 'USD', '2024-09-26'::date, ARRAY['1080p at 60 fps preferred', 'Hands and face must remain fully in frame', 'Include sign label slate at start'], ARRAY['Contributors must sign consent and release', 'Neutral background and clothing', 'No jewelry that obscures hand pose'], true, 'approved', 'Accessibility advisor approved lighting guidelines.', '835f1b30-f7ac-4358-91ce-2fbe205cac7d', '2024-07-02T21:10:00Z'::timestamptz, 'per_contribution', 25200, 4480, 'partial', 12, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/sign-language-gestures.jpg'),
('622e1b9b-0b69-41ec-b8ba-b8b5dea74d92', 'Satellite Nighttime Urban Lighting', 'GeoLumens is benchmarking sustainable development indicators using nighttime satellite imagery. Contributors provide cloud-free composites for secondary cities worldwide along with human-verified land-use annotations.', 'other', 'image', 'active', 780, 120, 55.0, 'USD', '2024-10-18'::date, ARRAY['Radiance-calibrated GeoTIFF', 'Cloud cover under 5%', 'Include vector mask for water bodies'], ARRAY['Minimum area 15x15 km', 'Attach write-up of image correction workflow', 'Reference sensor and acquisition date'], false, 'approved', 'Awaiting second tranche payment authorization.', 'e17eb4c4-707d-48ee-ae9b-2f609e6be99a', '2024-07-03T13:55:00Z'::timestamptz, 'upfront', 42900, 21450, 'partial', 9, 'https://jnrtvihcqlefhwvxtfcy.supabase.co/storage/v1/object/public/dataset-images/satellite-nightlight.jpg');
